import { VariableSet, LookupMultipleChoiceVariable, LookupSelectBoxVariable } from '@servicenow/sdk/core'
VariableSet({
    $id: Now.ID['lookup_test_set'],
    title: 'Lookup Test',
    type: 'multiRow',
    variables: {
        // Lookup Multiple Choice from Table
        usersMultipleTable: LookupMultipleChoiceVariable({
            question: 'Select Users (Table)',
            order: 1,
            lookupFromTable: 'sys_user',
            lookupValueField: 'sys_id',
            lookupLabelFields: ['name', 'email'],
            lookupPriceField: 'cost_center',
            lookupRecurringPriceField: 'department',
            referenceQual: 'active=true',
            includeNone: true,
            uniqueValuesOnly: false,
        }),
        // Lookup Multiple Choice from Choices
        priorityMultipleChoices: LookupMultipleChoiceVariable({
            question: 'Select Priority (Choices)',
            order: 2,
            lookupSource: 'choices',
            choiceTable: 'incident',
            choiceField: 'priority',
            choicesDependOn: 'category',
            choiceDirection: 'down',
            includeNone: true,
            uniqueValuesOnly: true,
        }),
        // Lookup Select Box from Table
        userSelectTable: LookupSelectBoxVariable({
            question: 'Select User (Table)',
            order: 3,
            lookupFromTable: 'sys_user',
            lookupValueField: 'user_name',
            lookupLabelFields: ['name', 'title'],
            referenceQual: 'active=true^company.name=ACME',
            includeNone: false,
            uniqueValuesOnly: true,
        }),
        // Lookup Select Box from Choices
        stateSelectChoices: LookupSelectBoxVariable({
            question: 'Select State (Choices)',
            order: 4,
            lookupSource: 'choices',
            choiceTable: 'incident',
            choiceField: 'state',
            choicesDependOn: 'assignment_group',
            includeNone: true,
            uniqueValuesOnly: true,
        }),
    },
})
